Foundations.Algebra.Iso.refl:
/-- Every group is isomorphic to itself. -/
def refl (G : Type u) [Group G] : G ≃* G :=
  { Hom.id G with invFun := fun x => x, left_inv := fun _ => rfl, right_inv := fun _ => rfl }

Foundations.Combinatorics.HasClique:
/-- `V` contains a clique of colour `b` with `k` vertices. -/
def HasClique (c : Nat → Nat → Bool) (b : Bool) (k : Nat) (V : List Nat) : Prop :=
  ∃ S : List Nat, S ⊆ V ∧ S.Nodup ∧ S.length = k ∧ Clique c b S

Foundations.Algebra.zagier:
/-- **Zagier's involution** on triples of natural numbers. -/
def zagier (t : Nat × Nat × Nat) : Nat × Nat × Nat :=
  if t.1 + t.2.2 < t.2.1 then (t.1 + 2 * t.2.2, t.2.2, t.2.1 - t.1 - t.2.2)
  else if t.1 < 2 * t.2.1 then (2 * t.2.1 - t.1, t.2.1, t.1 + t.2.2 - t.2.1)
  else (t.1 - 2 * t.2.1, t.1 + t.2.2 - t.2.1, t.2.1)

Foundations.Bridges.Bij.symm:
/-- The inverse bijection. -/
def symm {α : Type u} {β : Type v} (e : Bij α β) : Bij β α :=
  ⟨e.invFun, e.toFun, e.right_inv, e.left_inv⟩

Foundations.Logic.FO.tvar:
/-- The code of the term substituted for variable `n` under `d` binders, given the
mode and the code `t` of the instantiating term. -/
def tvar (mode t d n : Nat) : Nat :=
  bif decide (n < d) then pair 0 n
  else bif mode == 0 then (bif n == d then trename d t else pair 0 (n - 1))
  else bif mode == 1 then pair 0 (n + 1)
  else bif n == d then pair 2 (pair 0 d) else pair 0 n

Foundations.Categories.Topos.and:
/-- **Internal conjunction** `∧ : Ω × Ω ⟶ Ω`: the characteristic map of the point
`⟨true, true⟩`. -/
def and : prod (Ω : C) Ω ⟶ Ω := classify (pair truth truth) (mono_from_one _)

Foundations.Algebra.Q:
/-- The `k`-th permutation with `0 ↦ 1`. -/
def Q (k : Fin 24) : Perm (Fin 5) :=
  ⟨fun x => look tblF k x, fun x => look tblFi k x, tbl_inv1 k, tbl_inv2 k⟩

Foundations.Logic.Computability.godelCod:
/-- The Gödel-sentence code for a proof enumerator `q`: on input `e`, it runs `q` on
`(e, e)`, i.e. it searches for a proof that "code `e` does not halt on `e`". -/
def godelCode (q : Code) : Code := .comp q (vec2 (.proj 0) (.proj 0))

Foundations.Algebra.conv:
/-- The **product** of integer polynomials given by coefficient sequences: the coefficient of
`xⁿ` in `G · H` is `∑_{k ≤ n} Gₖ H_{n-k}`. -/
def conv (G H : Nat → Int) (n : Nat) : Int := zsum (fun k => G k * H (n - k)) (n + 1)

Foundations.Combinatorics.HasMono:
/-- A monotone subsequence of length `n + 1` among the positions `≤ N`. -/
def HasMono (r : Nat → Nat → Prop) (a : Nat → Nat) (n N : Nat) : Prop :=
  ∃ s : Nat → Nat, (∀ p, p ≤ n → s p ≤ N) ∧ ∀ p q, p < q → q ≤ n → s p < s q ∧ r (a (s p)) (a (s q))

Foundations.Algebra.IsC3:
/-- `σ` is a 3-cycle. -/
def IsC3 {n : Nat} (σ : Perm (Fin n)) : Prop :=
  ∃ a b c, a ≠ b ∧ b ≠ c ∧ a ≠ c ∧ σ = c3 a b c

Foundations.Numbers.R.ContinuousAt:
/-- `f` is **continuous at `x`** (ε-δ definition). -/
def ContinuousAt (f : R → R) (x : R) : Prop :=
  ∀ ε : R, 0 < ε → ∃ δ : R, 0 < δ ∧ ∀ y, abs (y - x) < δ → abs (f y - f x) < ε

Foundations.Topology.SeqContinuousAt:
/-- `f` is **sequentially continuous at `x`**: `xₙ → x` implies `f xₙ → f x`. -/
def SeqContinuousAt (f : X → Y) (x : X) : Prop :=
  ∀ s : Nat → X, Converges s x → Converges (fun n => f (s n)) (f x)

Foundations.Algebra.aevalHom:
/-- Evaluation at `γ` is a ring homomorphism `F[x] → Ω`. -/
def aevalHom (F : Subfield Ω) (γ : Ω) : RingHom (Polynomial F) Ω :=
  (evalHom γ).comp (mapHom F.incl)

Foundations.Algebra.gaussMu:
/-- **Gauss's count** `μ`: the number of `k ∈ {1, …, (p-1)/2}` whose multiple `k·a` has least
residue exceeding `p/2`. -/
def gaussMu (a p : Nat) : Nat := (List.range (half p)).countP (fun k => decide (half p < res a p k))

Foundations.Categories.Bij.symm:
/-- The inverse bijection. -/
def Bij.symm {α : Type w} {β : Type w'} (e : Bij α β) : Bij β α :=
  ⟨e.invFun, e.toFun, e.right_inv, e.left_inv⟩

Foundations.Topology.CFun:
/-- **The space `C[a, b]`** of continuous functions on `[a, b]`, each represented by its continuous
extension that is constant outside `[a, b]`. -/
abbrev CFun (a b : R) : Type := {f : R → R // (∀ x, f (clamp a b x) = f x) ∧ ∀ x, R.ContinuousAt f x}

Foundations.Algebra.snocFam:
/-- Extend a family `σ : Fin k → G` by one more member `τ`. -/
def snocFam {G : Type u} {k : Nat} (σ : Fin k → G) (τ : G) : Fin (k + 1) → G :=
  fun i => if h : i.val < k then σ ⟨i.val, h⟩ else τ

Foundations.Logic.FO.betaDiv:
/-- The divisor term `1 + (i + 1)·B` of the β-function, with `i = v 4`, `B = v 3`
(the indices it has inside `betaF`). -/
def betaDiv : Term Arith := add (succ zero) (mul (succ (v 4)) (v 3))

Foundations.Logic.Valuation.update:
/-- Change the value of a valuation at a single atom `a` to `b`. -/
def update (v : Valuation) (a : Nat) (b : Bool) : Valuation :=
  fun n => if n = a then b else v n

Foundations.Geometry.EuclidAxiom:
/-- **Euclid's axiom** (A10) for a neutral plane. -/
def EuclidAxiom {P : Type} (N : NeutralPlane P) : Prop :=
  ∀ a b c d t, N.B a d t → N.B b d c → a ≠ d → ∃ x y, N.B a b x ∧ N.B a c y ∧ N.B x t y

Foundations.Topology.UnifOn:
/-- `fₙ → g` **uniformly on `S`**. -/
def UnifOn (fs : Nat → R → R) (g : R → R) (S : R → Prop) : Prop :=
  ∀ ε : R, 0 < ε → ∃ N, ∀ n, N ≤ n → ∀ x, S x → abs (fs n x - g x) < ε

Foundations.Categories.fstHom:
/-- The first projection of a direct product, as a homomorphism. -/
def fstHom (G H : Type u) [Group G] [Group H] : Foundations.Algebra.Hom (G × H) G :=
  ⟨fun p => p.1, fun _ _ => rfl⟩

Foundations.Numbers.Q.invFrac:
/-- The inverse of a fraction: `(a/b)⁻¹ = b/a` (moving the sign to the numerator), and the
"junk value" `0⁻¹ = 0`. -/
def invFrac (p : Frac) : Q :=
  if h : 0 < p.num then mk p.den p.num h
  else if h' : p.num < 0 then mk (-p.den) (-p.num) (by omega)
  else mk 0 1 Int.one_pos

Foundations.Algebra.ZModUnits:
/-- The **units of `ℤ/nℤ`**: residues modulo `n` that are coprime to `n`. Under
multiplication modulo `n` they form a group, written `(ℤ/nℤ)ˣ`. -/
def ZModUnits (n : Nat) : Type := {a : Fin n // Nat.Coprime a.val n}

Foundations.Logic.FO.isFormulaStep:
/-- One step of the formula test. -/
def isFormulaStep (q : Nat) : Nat :=
  bif fst (cvN q) == 0 then (bif snd (cvN q) == 0 then 1 else 0)
  else bif fst (cvN q) == 1 then isTermC (fst (snd (cvN q))) * isTermC (snd (snd (cvN q)))
  else bif fst (cvN q) == 2 || fst (cvN q) == 3 || fst (cvN q) == 4 then
    cvRec q (fst (snd (cvN q))) * cvRec q (snd (snd (cvN q)))
  else bif fst (cvN q) == 5 || fst (cvN q) == 6 then cvRec q (snd (cvN q))
  else 0

Foundations.Topology.MeasureTheory.Outer:
/-- **Carathéodory measurability.** `E` splits every test set additively. -/
def IsMeasurable (E : α → Prop) : Prop :=
  ∀ T : α → Prop, o.ν T = o.ν (fun x => T x ∧ E x) + o.ν (fun x => T x ∧ ¬ E x)

Foundations.Categories.typesColimit:
/-- The **colimit type** of a diagram of types: the disjoint sum `Σ_j F j` divided by the
equivalence relation generated by `x ∼ F f x`. -/
def typesColimit : Type u := Quot (ColimRel F)

Foundations.Algebra.FiniteType.card_subt:
/-- The number of elements of the subtype `{x // P x}` is the count of `P`. -/
theorem card_subtype (P : α → Prop) : card {x // P x} = count P :=
  @length_listSubtype _ P (fun _ => Classical.propDecidable _) elems

Foundations.Numbers.R.IsCauchySeq:
/-- A sequence of reals is **Cauchy** if its terms become arbitrarily close to each other. -/
def IsCauchySeq (a : Nat → R) : Prop :=
  ∀ ε : R, 0 < ε → ∃ N, ∀ m n, N ≤ m → N ≤ n → abs (a m - a n) < ε

Foundations.Geometry.NeutralPlane.Col:
/-- **Collinearity** in a neutral plane: one of the three points lies between the others. -/
def NeutralPlane.Col {P : Type} (N : NeutralPlane P) (a b c : P) : Prop :=
  N.B a b c ∨ N.B b c a ∨ N.B c a b

Foundations.Topology.IsCauchy:
/-- A sequence is **Cauchy** if its terms become arbitrarily close to each other. -/
def IsCauchy (s : Nat → X) : Prop :=
  ∀ ε : R, 0 < ε → ∃ N, ∀ m n, N ≤ m → N ≤ n → dist (s m) (s n) < ε

Foundations.Types.Lambda.church:
/-- The **Church numeral** `n̄ = λf. λx. fⁿ x`: the number `n` as the operation of
iterating a function `n` times. -/
def church (n : Nat) : Term := lam (lam (iterApp (var 1) (var 0) n))

Foundations.Algebra.Subgroup.inNormalize:
/-- `H`, viewed as a subgroup of its normaliser. -/
def Subgroup.inNormalizer (H : Subgroup G) : Subgroup (normalizer H) :=
  Subgroup.comap (Hom.subtype (normalizer H)) H

Foundations.Logic.Computability.diagonal:
/-- The diagonal code built from a would-be halting decider `h`: on input `e` it
searches for a zero of `h(e, e)`. -/
def diagonal (h : Code) : Code := .mu (.comp h (vec2 (.proj 1) (.proj 1)))

Foundations.Algebra.FinDim:
/-- A space is **finite-dimensional** if some finite family spans it. -/
def FinDim (V : Type v) [AddAbGroup V] [VectorSpace K V] : Prop :=
  ∃ n, ∃ u : Fin n → V, Spans K u

Foundations.Logic.FO.ruleC:
/-- The rules of natural deduction from shifted PA, on codes. -/
def ruleC (q : Nat) : Bool :=
  rC0 q || rC1 q || rC2 q || rC3 q || rC4 q || rC5 q || rC6 q || rC7 q || rC8 q || rC9 q || rC10 q || rC11 q || rC12 q || rC13 q || rC14 q || rC15 q || rC16 q || rC17 q

Foundations.Numbers.R.Tendsto:
/-- The sequence `a` **converges** to `L`: for every `ε > 0`, eventually `|aₙ − L| < ε`. -/
def Tendsto (a : Nat → R) (L : R) : Prop :=
  ∀ ε : R, 0 < ε → ∃ N, ∀ n, N ≤ n → abs (a n - L) < ε

Foundations.Geometry.Pt.Bet:
/-- **Betweenness** in `K²`: `b = a + t (c − a)` for some `t ∈ [0, 1]`. -/
def Bet (a b c : Pt K) : Prop :=
  ∃ t : K, 0 ≤ t ∧ t ≤ 1 ∧ b.x - a.x = t * (c.x - a.x) ∧ b.y - a.y = t * (c.y - a.y)

Foundations.Logic.FO.Ctx:
/-- The premises available in a judgement: shifted PA axioms and a finite list. -/
def Ctx (k : Nat) (Δ : List (Formula Arith)) : Theory Arith :=
  Theory.union (shiftPA k) (Theory.ofList Δ)

Foundations.Bridges.liftRel:
/-- A relation on representatives, lifted to classes: some representatives are related. -/
def _root_.Foundations.Bridges.liftRel (L : ZFSet → ZFSet → Prop) (X Y : ZFSet) : Prop :=
  ∃ p ∈ X, ∃ q ∈ Y, L p q

Foundations.Numbers.Cut.mul:
/-- Product of cuts, by the rule of signs from the product of non-negative cuts. -/
noncomputable def mul (A B : Cut) : Cut :=
  open Classical in
  if 0 ≤ A then (if 0 ≤ B then posMul A B else -posMul A (-B))
  else (if 0 ≤ B then -posMul (-A) B else posMul (-A) (-B))

Foundations.Bridges.Omega:
/-- The type of members of the set `ω` — the von Neumann natural numbers, viewed
as a type so that they can be compared with `N` and `Nat`. -/
abbrev Omega : Type 1 := {x : ZFSet // x ∈ ω}

Foundations.Logic.FO.rC0:
/-- Rule 0 on codes: assumption. -/
def rC0 (q : Nat) : Bool :=
  qtag q == 0 && decide (qdat q < llen (qD q)) && lnth (qD q) (qdat q) == qF q

Foundations.Topology.Topology.Continuous:
/-- A map is **continuous** if preimages of open sets are open. -/
def Continuous (τ : Topology X) (σ : Topology Y) (f : X → Y) : Prop :=
  ∀ V, σ.IsOpen V → τ.IsOpen (fun x => V (f x))

Foundations.Combinatorics.MonoSet:
/-- A **monochromatic set** of colour `b`: all pairs `x < y` from `S` have colour `b`. -/
def MonoSet (c : Nat → Nat → Bool) (b : Bool) (S : List Nat) : Prop :=
  ∀ x ∈ S, ∀ y ∈ S, x < y → c x y = b

Foundations.Algebra.quinticPoly:
/-- The polynomial `x⁵ - 6x + 3` over any commutative ring. -/
def quinticPoly (R : Type u) [CommRing R] : Polynomial R :=
  mk [Int.cast 3, Int.cast (-6), 0, 0, 0, 1]

Foundations.Logic.FO.Formula.shift:
/-- Shift all free variables up by one, making room for a new binder (used when a
formula is carried into the scope of a quantifier). -/
def shift (φ : Formula L) : Formula L := φ.subst fun n => .var (n + 1)

Foundations.Topology.MeasureTheory.DisjO:
/-- The sets `set b`, `b ∈ l`, are pairwise disjoint. -/
def DisjOn (set : β → α → Prop) (l : List β) : Prop :=
  l.Pairwise (fun b b' => ∀ x, set b x → set b' x → False)

Foundations.Topology.ContOn:
/-- `f` is **continuous on `S`** (within `S`): nearby points of `S` have nearby values. -/
def ContOn (f : R → R) (S : R → Prop) : Prop :=
  ∀ x, S x → ∀ ε : R, 0 < ε → ∃ δ : R, 0 < δ ∧ ∀ y, S y → abs (y - x) < δ → abs (f y - f x) < ε

Foundations.Algebra.McKaySet:
/-- McKay's set `X`: the necklaces of length `p` whose product is `1`. -/
def McKaySet (G : Type u) [Group G] (p : Nat) : Type u :=
  {x : Necklace G p // tprod (n := p) x = 1}

Foundations.Types.SystemF.succT:
/-- The **successor** `λn. Λα. λf. λx. f (n [α] f x)`. -/
def succT : Term :=
  lam (tlam (lam (lam (app (var 1) (app (app (tapp (var 2) (.tvar 0)) (var 1)) (var 0))))))

Foundations.Numbers.R.neg:
/-- Negation of reals: negate representing sequences term by term. -/
def neg : R → R :=
  Quotient.lift (fun a => mk (CauSeq.neg a)) (fun _ _ h => mk_eq_mk.2 (neg_equiv h))

Foundations.Categories.IsTerminal.unique:
/-- **Terminal objects are unique up to isomorphism.** -/
def IsTerminal.uniqueIso {T T' : C} (hT : IsTerminal T) (hT' : IsTerminal T') : T ≅ T' :=
  ⟨hT'.lift T, hT.lift T', hT.uniq _ _, hT'.uniq _ _⟩

Foundations.Algebra.Subfield.toSubring:
/-- A subfield, viewed as a subring. -/
def toSubring (K : Subfield Ω) : Subring Ω :=
  ⟨K.carrier, K.zero_mem, K.one_mem, K.add_mem, K.neg_mem, K.mul_mem⟩

Foundations.Logic.Ordinals.bump:
/-- **Bumping the base**: write `n` in hereditary base `c + 2` and replace every
`c + 2` by `c + 3`. -/
def bump (c n : Nat) : Nat := ev (c + 3) (ord c n)

Foundations.Logic.FO.substL:
/-- Substitution of a list of terms for the variables `0, 1, 2, …`. -/
def substL (ts : List (Term Arith)) (φ : Formula Arith) : Formula Arith :=
  φ.subst fun n => ts.getD n zero

Foundations.Logic.FO.isPAC:
/-- The test "`ψ` is an axiom of PA, with `χ` the formula of its induction instance". -/
def isPAC (ψ χ : Nat) : Bool :=
  (closedAx.map fcode).contains ψ || ψ == indC χ

Foundations.Topology.ContinuousAt:
/-- `f` is **continuous at `x`** (ε-δ). -/
def ContinuousAt (f : X → Y) (x : X) : Prop :=
  ∀ ε : R, 0 < ε → ∃ δ : R, 0 < δ ∧ ∀ y, dist y x < δ → dist (f y) (f x) < ε

Foundations.Logic.Computability.llen:
/-- Length of a coded list: the number of `i < l` with a non-empty `i`-fold tail. -/
def llen (l : Nat) : Nat := natRec (fun _ => 0)
  (fun p => snd (snd p) + (bif ldrop (fst p) (fst (snd p)) == 0 then 0 else 1)) l l

Foundations.Logic.FO.indAx:
/-- The induction axiom for `χ`. -/
def indAx (χ : Formula Arith) : Formula Arith :=
  imp (conj (χ.inst zero) (all (imp χ (χ.subst succSubst)))) (all χ)

Foundations.Topology.NowhereDenseClosed:
/-- A set is **nowhere dense and closed**: closed, and containing no ball. -/
def NowhereDenseClosed (F : X → Prop) : Prop :=
  IsClosed F ∧ ∀ x, ∀ ε : R, 0 < ε → ∃ y, dist x y < ε ∧ ¬ F y

Foundations.Algebra.InSpan:
/-- `x` is in the **span** of `u` if it is a linear combination `∑ cᵢ uᵢ`. -/
def InSpan {ι : Type w} [FiniteType ι] (u : ι → V) (x : V) : Prop :=
  ∃ c : ι → K, x = isum (fun i => c i • u i)

Foundations.Logic.FO.haltsSigma:
/-- The Σ₁ formula "program `c` halts on `x`" (free variable `0 = x`):
`∃y ∃w grb c 1 (y, x, w)`. -/
def haltsSigma (c : Code) : Formula Arith := ex (evalSigma c)

Foundations.Numbers.R.avoidStep:
/-- One step of Cantor's construction: of the interval `[a, b]`, keep the upper third if `y` lies
below it, and otherwise the lower third (which then lies below `y`). -/
noncomputable def avoidStep (y : R) (p : Q × Q) : Q × Q :=
  open Classical in
  if y < ofQ ((p.1 + 2 * p.2) / 3) then ((p.1 + 2 * p.2) / 3, p.2)
  else (p.1, (2 * p.1 + p.2) / 3)

Foundations.Algebra.famOver:
/-- The members of `H`, viewed as automorphisms of `L` over `Fix(H)`. -/
def famOver (i : Fin n) : FieldAut (famFix σ) L :=
  (σ i).toOver fun _ ⟨_, hx⟩ => hx (σ i) ⟨i, rfl⟩

Foundations.Logic.FO.isTermStep:
/-- One step of the term test (value `1` = "is a term code"). -/
def isTermStep (q : Nat) : Nat :=
  bif fst (cvN q) == 0 then 1
  else bif fst (cvN q) == 1 then (bif snd (cvN q) == 0 then 1 else 0)
  else bif fst (cvN q) == 2 then cvRec q (snd (cvN q))
  else bif fst (cvN q) == 3 || fst (cvN q) == 4 then
    cvRec q (fst (snd (cvN q))) * cvRec q (snd (snd (cvN q)))
  else 0

Foundations.Algebra.QuotientGroup:
/-- **Quotient group.** `G ⧸ N` is the type of left cosets of `N`, obtained by abstraction
from the relation `a⁻¹ * b ∈ N`. -/
def QuotientGroup (N : Subgroup G) : Type u := Quotient (cosetSetoid N)

Foundations.Numbers.C.CTendsto:
/-- A sequence of complex numbers **converges** to `L` if its real and imaginary parts do. -/
def CTendsto (s : Nat → C) (L : C) : Prop :=
  Tendsto (fun n => (s n).re) L.re ∧ Tendsto (fun n => (s n).im) L.im

Foundations.Logic.FO.rC10:
/-- Rule 10 on codes: ex falso. -/
def rC10 (q : Nat) : Bool :=
  qtag q == 10 && decide (0 < llen (qjs q)) && qprem q 0 == pj (qk q) (qD q) 0

Foundations.Categories.typesLimit:
/-- The **limit type** of a diagram of types: compatible families `(x_j)_j` with
`F f (x_i) = x_j` for every arrow `f : i ⟶ j` — a subtype of the product `∏_j F j`. -/
def typesLimit : Type u := {x : (j : J) → F.obj j // ∀ {i j : J} (f : i ⟶ j), F.map f (x i) = x j}

Foundations.Logic.Computability.covRec:
/-- **Course-of-values recursion.** `covRec g x n = g ⟨x, ⟨n, H⟩⟩` where `H` codes the
list of all earlier values `covRec g x m`, `m < n` (read with `histGet`). -/
def covRec (g : Nat → Nat) (x n : Nat) : Nat := g (pair x (pair n (covHist g x n)))

Foundations.Algebra.Polynomial.eval:
/-- **Evaluation** of a polynomial at `x`. -/
def eval (x : R) (p : Polynomial R) : R :=
  Quotient.lift (s := PolyList.setoid R) (evalList x) (fun a b h => evalList_congr x (show Eqv a b from h)) p

Foundations.Algebra.evalMapHom:
/-- `p ↦ (σ p)(δ)` as a ring homomorphism `F[x] → E`. -/
def evalMapHom (σ : RingHom F E) (δ : E) : RingHom (Polynomial F) E :=
  (evalHom δ).comp (mapHom σ)

Foundations.Logic.FO.rC16:
/-- Rule 16 on codes: reflexivity of equality. -/
def rC16 (q : Nat) : Bool :=
  qtag q == 16 && fst (qF q) == 1 && fst (snd (qF q)) == snd (snd (qF q))

Foundations.Categories.sndHom:
/-- The second projection of a direct product, as a homomorphism. -/
def sndHom (G H : Type u) [Group G] [Group H] : Foundations.Algebra.Hom (G × H) H :=
  ⟨fun p => p.2, fun _ _ => rfl⟩

Foundations.Algebra.FieldAut.toOver:
/-- An automorphism over `K` that also fixes a larger subfield `M` is an automorphism over `M`. -/
def toOver {M : Subfield Ω} (σ : FieldAut K L) (h : ∀ x : L, x.1 ∈ M → σ.toFun x = x) :
    FieldAut M L :=
  { σ with fix := h }

Foundations.Algebra.foldFin:
/-- The folding map as a map `Fin h → Fin h`. -/
def foldFin (hp : IsPrime p) (hodd : p % 2 = 1) (ha : ¬ p ∣ a) (k : Fin (half p)) : Fin (half p) :=
  ⟨fold a p k.val - 1, by have := fold_bounds hp hodd ha k.isLt; omega⟩

Foundations.Logic.Computability.treeStep:
/-- The one-step check for course-of-values tree validation. Its argument is
`⟨_, ⟨t, H⟩⟩` with `H` the history of validity values below `t`. -/
def treeStep (q : Nat) : Nat :=
  let t := fst (snd q)
  let js := fst (snd t)
  let cs := snd (snd t)
  (step (fst (fst t)) (snd (fst t)) js &&
    llen js == llen cs &&
    ballLt (fun r =>
        let q := fst r
        let i := snd r
        let t := fst (snd q)
        let H := snd (snd q)
        let js := fst (snd t)
        let cs := snd (snd t)
        decide (lnth cs i < t) && histGet H t (lnth cs i) == 1 &&
          troot (lnth cs i) == lnth js i)
      q (llen cs)).toNat

Foundations.Logic.FO.diagC:
/-- **The diagonal function** on Gödel numbers: substitute the numeral of `n` into
the formula with code `n`. -/
def diagC (n : Nat) : Nat := instC n (ncode n)

Foundations.Algebra.Polynomial.coeff:
/-- The `n`-th coefficient of a polynomial. -/
def coeff (p : Polynomial R) (n : Nat) : R :=
  Quotient.lift (s := PolyList.setoid R) (fun l => PolyList.coeff l n) (fun a b h => (show Eqv a b from h) n) p

Foundations.Algebra.skip:
/-- Skipping index `p`: an enumeration of `Fin (m+1) \ {p}` by `Fin m`. -/
def skip {m : Nat} (p : Fin (m + 1)) (i : Fin m) : Fin (m + 1) :=
  if i.val < p.val then ⟨i.val, by omega⟩ else ⟨i.val + 1, by omega⟩

Foundations.Algebra.isum:
/-- **Sum over a finite type**: `∑ᵢ f i`, summing over the census. -/
def isum {A : Type u} [AddAbGroup A] {ι : Type v} [FiniteType ι] (f : ι → A) : A :=
  lsum ((elems : List ι).map f)
